const cq = $json.callback_query || {};
const data = String(cq.data || '');
const decision = data.split(':')[0] === 'approve' ? 'approved' : 'rejected';
const rid = (data.split(':')[1] || '').match(/^[0-9a-f-]{36}$/i) ? data.split(':')[1] : null;
const user = String((cq.from && (cq.from.username || cq.from.id)) || 'inconnu').replace(/[^\w.@-]/g, '');
const chat = (cq.message && cq.message.chat && cq.message.chat.id) || '';
if (!rid) { throw new Error('request_id invalide dans callback_data'); }
const comment = ('via Telegram: ' + user).split('$c$').join('');
const sql = `select fn_record_decision('${rid}'::uuid, 'human', (select id from people where role='founder_final_approver' limit 1), 'human', '${decision}', $c$${comment}$c$) as resultat;`;
return [{ json: { sql, decision, chat_id: chat } }];
